PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://w3id.org/brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?temp ?hset ?cset ?tsid ?tsidT ?tsidH ?tsidC WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_mid_ZN_4" .
  ?zone brick:hasPoint
    ?temp .
  ?temp a brick:Air_Temperature .
  OPTIONAL { ?zone brick:hasPoint ?hsp . ?hsp a brick:HeatingSetpoint }
  OPTIONAL { ?zone brick:hasPoint ?csp . ?csp a brick:CoolingSetpoint }
  OPTIONAL { ?temp ref:hasExternalReference ?tsidT . ?tsidT ref:hasTimeseriesId ?tsidT }
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
} LIMIT 50

